// web/js/stream.js — WebSocket 实时事件流客户端（74行）
// 纯 JS 实现，无框架依赖，支持自动重连

function buildWsUrl() {
  const proto = location.protocol === "https:" ? "wss:" : "ws:";
  return `${proto}//${location.host}/api/runtime-stream`;
}

export function createStreamClient({
  reconnectDelayMs = 2000,
  maxReconnectDelayMs = 30_000,
  onEvent = () => {},
  onConnect = () => {},
  onDisconnect = () => {},
} = {}) {
  let socket = null;
  let currentDelay = reconnectDelayMs;

  function scheduleReconnect() {
    // 指数退避重连：2s → 4s → 8s → ... → 最大 30s
    currentDelay = Math.min(Math.floor(currentDelay * 2), maxReconnectDelayMs);
    reconnectTimer = setTimeout(() => connect(), currentDelay);
  }

  function connect() {
    socket = new WebSocket(buildWsUrl());
    socket.onopen = () => {
      currentDelay = reconnectDelayMs;  // 连接成功，重置退避
      onConnect();
    };
    socket.onmessage = (event) => {
      try { onEvent(JSON.parse(event.data)); } catch { /* 忽略畸形消息 */ }
    };
    socket.onclose = () => {
      socket = null;
      onDisconnect();
      scheduleReconnect();  // 断线后自动重连
    };
  }

  return { connect, disconnect: () => { stopped = true; socket?.close(); } };
}

// web/js/api.js — 后端 API 客户端（598行）
// 从页面 origin 派生 BASE_URL，所有请求保持同源
// HttpOnly session cookie 和 WebSocket 握手自动携带

const BASE_URL = `${location.protocol}//${location.host}/api`;
const DEFAULT_READ_TIMEOUT_MS = 12_000;
const CSRF_HEADER = "X-OBC-Auth";

// 请求去重：使用 request_id 防止重试导致的重复操作
// 持久化到 localStorage，页面刷新后仍能追踪进行中的请求
const pendingRequestIds = new Map();

function newRequestId() {
  if (typeof globalThis.crypto?.randomUUID === "function")
    return globalThis.crypto.randomUUID();
  return `${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}`;
}

